class Solution {
public:
    int minPushBox(vector<vector<char>>& grid) {
        int rows = grid.size(), cols = grid[0].size();
        int cells = rows * cols;
        int player = -1, box = -1, target = -1;
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                int p = r * cols + c;
                if (grid[r][c] == 'S') player = p;
                if (grid[r][c] == 'B') box = p;
                if (grid[r][c] == 'T') target = p;
            }
        }
        auto valid = [&](int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols &&
                   grid[r][c] != '#';
        };
        const int dr[4] = {-1, 1, 0, 0};
        const int dc[4] = {0, 0, -1, 1};
        const int INF = INT_MAX / 2;
        vector<int> dist(cells * cells, INF);
        deque<pair<int, int>> dq;
        dist[box * cells + player] = 0;
        dq.push_front({box, player});
        while (!dq.empty()) {
            int b = dq.front().first, p = dq.front().second;
            dq.pop_front();
            int current = dist[b * cells + p];
            // Relax all reachable states; no early return on a stale queue entry.
            int pr = p / cols, pc = p % cols;
            for (int d = 0; d < 4; ++d) {
                int nr = pr + dr[d], nc = pc + dc[d];
                if (!valid(nr, nc)) continue;
                int np = nr * cols + nc, nb = b, cost = 0;
                if (np == b) {
                    int br = b / cols + dr[d], bc = b % cols + dc[d];
                    if (!valid(br, bc)) continue;
                    nb = br * cols + bc;
                    cost = 1;
                }
                int key = nb * cells + np;
                if (current + cost < dist[key]) {
                    dist[key] = current + cost;
                    if (cost) dq.push_back({nb, np});
                    else dq.push_front({nb, np});
                }
            }
        }
        int best = INF;
        for (int p = 0; p < cells; ++p)
            best = min(best, dist[target * cells + p]);
        return best == INF ? -1 : best;
    }
};
